// The deck's slide text, the meeting and what the presenter wants from it (docs/CONTRACT.md, POST /deck-research)
const req = $('A deck was uploaded (laptop)').first().json.body;
const row = $input.first().json || {};
const parse = x => { try { return x ? JSON.parse(x) : null; } catch (e) { return null; } };
const proposal = parse(row.proposal) || {};
const goal = req.goal || (proposal.goal && proposal.goal.text) || '';
const offer = (req.presenter && req.presenter.offer) || '';
const slides = ((req.deck && req.deck.slides) || []).map(s => ({ index: s.index, text: String(s.text || '').slice(0, 1200) })).filter(s => s.text);
const meeting = (row.title || 'A meeting') + (row.company ? ' with ' + row.company : '');
const side = (offer ? 'They offer: ' + offer + '. ' : '') + (goal ? 'They want: ' + goal + '.' : '') || 'Not given.';
const parts = { meeting, side, deck: JSON.stringify(slides) };
const PROMPT = "You are preparing a presenter for a real meeting. Read their deck and plan how to find who else already does what
it pitches: competitors, big companies with a similar product, startups, government or defence programmes, research labs.

The meeting: {meeting}
What the presenter offers and wants from it: {side}
The deck, slide by slide (index from 0):
{deck}

about: one sentence on what the deck pitches and to whom, in plain words.
searches: 2 or 3 Google News searches that would surface others doing the same thing, the most specific first. Each:
- query: 3 to 5 words naming the kind of product or solution the way a journalist would (e.g. "engine health monitoring drones",
  "AI route optimisation logistics"), never the presenter's own product name, project title or team; spell out acronyms the way the
  deck means them; no quotes or operators;
- broad: a broader search, 2 or 3 words, for when the first finds nothing (e.g. "predictive maintenance aircraft");
- slide_index: the slide where a panel would bring the competition up: the slide that says what is new or different, or the solution
  slide (never the title slide unless the deck has nothing else).
Answer in JSON.";
const prompt = Object.entries(parts).reduce((t, [k, v]) => t.split('{' + k + '}').join(v), PROMPT);
// Each slide's first line, so the model can place who it finds on a slide
const titles = slides.map(s => s.index + ': ' + s.text.split('
')[0].trim().slice(0, 90)).join('; ');
return [{ json: { meeting_id: row.meeting_id || '', found: !!row.meeting_id, meeting, indexes: slides.map(s => s.index), titles, prompt } }];

