const replyText = j => j.choices
  ? ((j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '')
  : ((j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts) || []).map(p => p.text || '').join('');

// Each planned search on Google News, then its broader one: at most six, no repeats
const g = $('Read the deck').first().json;
const d = JSON.parse(replyText($input.first().json) || '{}');
const clean = q => String(q || '').split('"').join('').trim();
const seen = new Set();
const fallback = g.indexes.length > 1 ? g.indexes[1] : (g.indexes[0] || 0);
const qs = (d.searches || []).flatMap(x => [clean(x.query), clean(x.broad)].filter(Boolean)
  .map(q => ({ q, slide_index: g.indexes.includes(x.slide_index) ? x.slide_index : fallback })))
  .filter(x => !seen.has(x.q.toLowerCase()) && seen.add(x.q.toLowerCase())).slice(0, 6);
// Nothing to search still goes on (one empty search that fails quietly), so the laptop always gets an answer
if (!qs.length) return [{ json: { none: true, about: d.about || '', url: '' } }];
const url = q => 'https://news.google.com/rss/search?q=' + encodeURIComponent(q) + '&hl=en-IN&gl=IN&ceid=IN:en';
return qs.map(x => ({ json: { ...x, about: d.about || '', url: url(x.q) } }));

// Every headline found (date, publisher, link), without repeats, numbered for the model to cite
const g = $('Read the deck').first().json;
const all = $('The searches').all().map(i => i.json);
const results = $input.all().map(i => String(i.json.data || ''));
const unescape = t => t.replace(/<!\[CDATA\[|\]\]>/g, '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'");
const tag = (xml, t) => { const m = xml.match(new RegExp('<' + t + '[^>]*>([^]*?)</' + t + '>')); return m ? unescape(m[1]).trim() : ''; };
const headlines = xml => xml.split('<item>').slice(1).map(it => {
  const src = it.match(/<source url="([^"]*)">([^]*?)<\/source>/);
  const date = new Date(tag(it, 'pubDate'));
  return { title: tag(it, 'title').replace(/ - [^-]+$/, ''), url: tag(it, 'link'), publisher: src ? unescape(src[2]) : '', date: isNaN(date) ? '' : date.toISOString().slice(0, 10) };
}).filter(h => h.title && h.url);
// Six from each search in turn, so one broad search can't crowd out the specific ones
const seen = new Set();
const sources = [];
const per = all.map((x, k) => x.none ? [] : headlines(results[k] || '').slice(0, 6));
for (let round = 0; round < 6; round++) per.forEach(list => {
  const h = list[round];
  if (h && sources.length < 16 && !seen.has(h.title.toLowerCase())) { seen.add(h.title.toLowerCase()); sources.push(h); }
});
const text = sources.map((h, i) => '[' + (i + 1) + '] ' + h.title + (h.publisher ? ' (' + h.publisher + (h.date ? ', ' + h.date : '') + ')' : '')).join('\n');
const about = (all[0] && all[0].about) || 'Not given.';
const parts = { meeting: g.meeting, about, slides: g.titles || 'None.', headlines: text || 'No headlines found.' };
const PROMPT = "You find who else already does what a presenter pitches, before a real meeting, so the panel can ask how they\nare different. Say only what the sources say.\n\nThe meeting: {meeting}\nWhat the deck pitches: {about}\nThe deck's slides (index, title line): {slides}\n\nHeadlines found (numbered sources; many will share a word or an acronym but be about something else):\n{headlines}\n\nothers: up to 4 companies, products, programmes or labs that the headlines show already building or running the same or nearly the\nsame thing as the deck (the same problem for the same kind of user, or the same technology for the same use). Leave out: a headline\nabout the wider field (e.g. \"AI in defence\", \"drones in agriculture\"), a trend piece, explainer or opinion, a company only investing,\nhiring or seeking partners, and a hobby project. Most decks have 0 to 2; an empty list is a fine answer. Each:\n- name: who does the work, as the headline names them (e.g. \"HAL\", \"an IIT Delhi startup\"); never the publisher, the outlet or a\n  think tank writing about it (if the headline doesn't say who, name the programme, e.g. \"the Su-30 MKI health index\");\n- what: what the source says they do, in one plain sentence, with the date where the headline gives one; nothing beyond the headline;\n- close: \"same\" if they do what the deck pitches, \"near\" if it overlaps (the same technology on the same kind of machine or user, or\n  the same problem for the same user solved another way); the same technology in an unrelated field (railways for an aircraft deck)\n  is neither: leave it out;\n- slide_index: the slide where the panel would bring them up (from the slides above);\n- question: how someone on the panel would put it, naming them, in one short sentence (e.g. \"HAL already monitors these engines.\n  What does yours do that theirs doesn't?\");\n- sources: the numbers of the headlines it rests on (at least one).\nAnswer in JSON.";
const prompt = Object.entries(parts).reduce((t, [k, v]) => t.split('{' + k + '}').join(v), PROMPT);
const counts = {};
all.forEach((x, k) => { if (!x.none) counts[x.q] = { query: x.q, slide_index: x.slide_index, found: headlines(results[k] || '').length }; });
return [{ json: { searched: Object.values(counts), about, sources, prompt } }];

